    /**
     * What it takes to draw this vehicle, or null for one no script
     * declares -- a mod's own, most likely.
     *
     * @return array{
     *     model: string,
     *     texture: string|null,
     *     mask: string|null,
     *     scale: float,
     *     length: float,
     *     width: float,
     *     wheelMesh: string,
     *     wheelTexture: string,
     *     wheels: list<array{x: float, y: float, z: float, radius: float, width: float}>
     * }|null
     */
    public static function find(string $script): ?array
    {
        // The panel receives "Base.PickUpVan"; the scripts name it
        // "PickUpVan".
        $name = str_contains($script, '.') ? substr($script, strrpos($script, '.') + 1) : $script;
        $entry = self::ENTRIES[$name] ?? null;

        if ($entry === null) {
            return null;
        }

        return [
            'model' => $entry[0].'.fbx',
            'texture' => $entry[1] === null ? null : $entry[1].'.png',
            'mask' => $entry[2] === null ? null : $entry[2].'.png',
            'scale' => $entry[3],
            'length' => $entry[4],
            'width' => $entry[5],
            'wheelMesh' => self::WHEEL_MESH,
            'wheelTexture' => self::WHEEL_TEXTURE,
            'wheels' => array_map(
                static fn (array $wheel): array => [
                    'x' => $wheel[0],
                    'y' => $wheel[1],
                    'z' => $wheel[2],
                    'radius' => $wheel[3],
                    'width' => $wheel[4],
                ],
                $entry[6],
            ),
        ];
    }

    /** @return list<string> */
    public static function scripts(): array
    {
        return array_keys(self::ENTRIES);
    }
}
